import bundle from "./worldbank.json" with { type: "json" };
import type { Dataset } from "../../types/dataset.ts";

/**
 * Datasets imported programmatically from the World Bank API.
 *
 * Generated by `npm run import:wb` - do not hand-edit worldbank.json. Every
 * value in it is the source's own published observation for that
 * country-year, fetched over the API and rounded, never interpolated. That
 * is what earns these a green reliability rating, and it is checkable:
 * `sourceSeriesId` records the exact indicator and country, so re-running
 * the importer reproduces the same numbers.
 *
 * Kept in a separate array from the hand-authored `curatedDatasets` because
 * the two carry provenance in genuinely different ways. A curated dataset's
 * paper trail is a human-reviewed row in data/SOURCES.md; an imported one's
 * is an API endpoint anyone can call. scripts/validate-datasets.ts applies
 * the appropriate check to each rather than pretending one rule fits both.
 */
type ImportedRow = {
  slug: string; title: string; question: string;
  yLabel: string; yUnit: string;
  xValues: string[]; yValues: number[];
  revealFromIndex: number; yDomain: number[];
  sourceName: string; sourceUrl: string;
  verified: boolean; isActive: boolean;
  reliability: "green" | "yellow";
  reliabilityNote: string | null;
  sourceSeriesId: string; sourceFetchedAt: string;
};

/*
 * Mapped field by field rather than cast. A blanket `as Dataset[]` compiled
 * happily while the bundle was missing `verifiedOn` entirely and had widened
 * yDomain from a 2-tuple to number[] - exactly the kind of drift a cast is
 * good at hiding and a mapping cannot.
 */
export const generatedDatasets: Dataset[] = (bundle as ImportedRow[]).map((row) => ({
  slug: row.slug,
  title: row.title,
  question: row.question,
  yLabel: row.yLabel,
  yUnit: row.yUnit,
  xValues: row.xValues,
  yValues: row.yValues,
  revealFromIndex: row.revealFromIndex,
  yDomain: [row.yDomain[0], row.yDomain[1]],
  sourceName: row.sourceName,
  sourceUrl: row.sourceUrl,
  verified: row.verified,
  verifiedOn: null,
  isActive: row.isActive,
  reliability: row.reliability,
  reliabilityNote: row.reliabilityNote,
  sourceSeriesId: row.sourceSeriesId,
}));
